import json
r=json.load(open('recs.json'));tl=json.load(open('tl.json'))
ins=set('45175 44049 32894 47639 35947 36330 49130 37712 39638 32200 48146 49580 36107 31279 45269 37488 32319 49946 43699 38571 45677 40672 31527 31564 44873 43840 49301 45172'.split())
P=lambda x,k:x['properties'].get(k,{}).get('value')
b=[x for x in r.values() if x['parent_id']=='db-duty-actuals-from-0915' and P(x,'Staff number') in ins and P(x,'Type')=='Flight duty']
idx={}
for k,v in tl.items():
  for s in v['secs']: idx.setdefault((v['ac'],s[1]),[]).append((k,v['date']))
n=0
for x in b:
  fl=(P(x,'Flights') or '').split()
  hits=set()
  for f in fl:
    for k,d in idx.get((P(x,'Aircraft'),f),[]): 
      if d==P(x,'Report (UTC)')[:10] or d==(P(x,'On-blocks last sector (UTC)') or '')[:10]: hits.add(k)
  if hits:
    n+=1
    for k in hits: print(P(x,'Duty ref'),P(x,'Staff number'),P(x,'Aircraft'),fl,P(x,'Report (UTC)'),P(x,'On-blocks last sector (UTC)'),P(x,'Sectors'),'->',k,tl[k]['secs'])
print(n,len(b))
"

