arguments.command:
cd /workspace/work; python3 -c "
import json
o=json.load(open('final.json'))
r=json.load(open('recs.json'))
em={x['properties']['Staff number']['value']:x['properties']['Email']['value'] for x in r.values() if x['parent_id']=='db-crew-register'}
by={}
for i,f in enumerate(o): by.setdefault(f['s'],[]).append((f'FTL-{i+1:05d}',f))
out=[]
for s in sorted(by):
  lines=[f\"{ref} {f['ref']} {f['lt']} excess {f['exc']} min\" for ref,f in by[s]]
  out.append(dict(s=s,to=em[s],refs=[r for r,_ in by[s]],body='\n'.join(lines)))
json.dump(out,open('notices.json','w'),indent=1)
for n in out: print(n['s'],n['to'],repr(n['body']))
"

